using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json.Linq;
public static class B1DeskCapture {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-12_B1_DeskProps/";
 static void Shot(string n,Transform t,Vector3 eye,Vector3 target,float fov){var go=new GameObject("DeskReviewCamera"){hideFlags=HideFlags.HideAndDontSave};var c=go.AddComponent<Camera>();c.transform.position=t.TransformPoint(eye);c.transform.LookAt(t.TransformPoint(target));c.fieldOfView=fov;c.nearClipPlane=.025f;c.farClipPlane=180;c.useOcclusionCulling=false;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1600,1100,24){antiAliasing=4};var old=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1600,1100,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1100),0,0);tex.Apply();File.WriteAllBytes(O+n+".jpg",tex.EncodeToJPG(93));}finally{c.targetTexture=null;RenderTexture.active=old;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Run(string prefix){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B1_Circular.unity"))throw new Exception("Saved B1 required");Directory.CreateDirectory(O);var a=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B1_DeskPropRefinement/before.json"));var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool enabled=player.activeSelf;player.SetActive(false);int n=0;try{foreach(var q in a["props"]){string model=(string)q["model"],name=(string)q["name"];if(model=="BL_HandheldRecorder")continue;var t=GameObject.Find((string)q["path"]).transform;bool table=model.Contains("Table")||model=="BL_DiningSet";Shot(prefix+"_"+name,t,new Vector3(.1f,table?2.05f:1.7f,table?1.8f:1.15f),new Vector3(0,table?.83f:1,0),table?68:68);n++;if(model=="BL_ResearchDesk"||model.Contains("OperatorDesk")){Shot(prefix+"_detail_"+name,t,new Vector3(0,1.35f,.68f),new Vector3(0,.86f,.13f),60);n++;}}}finally{player.SetActive(enabled);EditorSceneManager.OpenScene(s.path);}return new{images=n};}
 public static object Features(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool enabled=player.activeSelf;player.SetActive(false);int n=0;try{var t=GameObject.Find("B1_C01_Data_ResearchDesk_01").transform;var lod=t.Find("DesktopRefinement").GetComponent<LODGroup>();lod.ForceLOD(0);Shot("close_keyboard",t,new Vector3(0,1.15f,.49f),new Vector3(0,.852f,.18f),65);Shot("close_mouse",t,new Vector3(-.405f,1.04f,.43f),new Vector3(-.405f,.85f,.18f),50);Shot("close_mouse_top",t,new Vector3(-.405f,1.23f,.20f),new Vector3(-.405f,.85f,.19f),30);Shot("close_mouse_front",t,new Vector3(-.405f,1.04f,-.07f),new Vector3(-.405f,.85f,.19f),50);n+=4;lod.ForceLOD(-1);foreach(string name in new[]{"B1_C01_Data_ResearchDesk_01","B1_E01_SC_OperatorDesk_A_02","B1_W02_DiningSet_01"}){t=GameObject.Find(name).transform;lod=t.Find("DesktopRefinement").GetComponent<LODGroup>();for(int level=0;level<3;level++){lod.ForceLOD(level);Shot("lod"+level+"_"+name,t,new Vector3(.1f,1.8f,1.75f+level*2.8f),new Vector3(0,1,0),65);n++;}lod.ForceLOD(-1);}}finally{player.SetActive(enabled);EditorSceneManager.OpenScene(s.path);}return new{images=n};}
}
